-- Users cache populated from AD at every login (source of truth stays AD).
-- Passwords are NEVER stored here (S-03/S-09).
-- PK is a UUIDv7 generated by the application (time-ordered, index-friendly).
CREATE TABLE IF NOT EXISTS users (
    id            uuid PRIMARY KEY,
    username      text NOT NULL UNIQUE,
    dn            text NOT NULL,
    display_name  text NOT NULL DEFAULT '',
    email         text NOT NULL DEFAULT '',
    roles         text[] NOT NULL DEFAULT '{}',
    last_login_at timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    deleted_at    timestamptz,             -- NULL = active profile (soft delete)
    CONSTRAINT users_username_format CHECK (username <> '')
);

-- Fast lookup of active profiles by username (login upsert / auth flows).
CREATE INDEX IF NOT EXISTS idx_users_active ON users (username) WHERE deleted_at IS NULL;
-- Admin listing filters by status.
CREATE INDEX IF NOT EXISTS idx_users_deleted_at ON users (deleted_at);
